    'dl.badge':      'Offizielle Formulare',
    'dl.h1':         'Formulare herunterladen',
    'dl.desc':       'Laden Sie alle offiziellen Formulare der Botschaft kostenlos herunter. Ausfüllen, ausdrucken und zum Termin mitbringen.',
    'dl.cat.passport':'Reisepass & Identität',
    'dl.cat.visa':   'Visum',
    'dl.cat.civil':  'Zivilstand',
    'dl.cat.official':'Offizielle Dokumente',
    'dl.cat.fees':   'Kanzleigebühren',
