    'ann.pinned.desc':     'Die Botschaft von Côte d\'Ivoire in Wien ist am <strong>Freitag, 7. August 2026</strong> anlässlich des Nationalfeiertags der Republik Côte d\'Ivoire (66. Jahrestag der Unabhängigkeit) geschlossen. Die Dienste werden am Montag, 10. August 2026 um 09:30 Uhr wieder normal aufgenommen.',
