    /* Titel & Texte der Ankündigungen */
    'ann.a1.title': 'Wirtschaftsmission: Aka Aouélé leitet eine Delegation des Wirtschafts-, Sozial-, Umwelt- und Kulturrats (CESEC) nach Österreich',
    'ann.a1.desc':  'Der Präsident des CESEC, Aka Aouélé, hat eine ivorische Delegation nach Österreich geführt, um den Austausch und die Zusammenarbeit zwischen Côte d\'Ivoire und ihren europäischen Partnern zu stärken.',
    'ann.a2.title': 'Die ivorische Diplomatie geehrt in Wien: Côte d\'Ivoire übernimmt den Vorsitz der Organisation des Vertrags über das umfassende Verbot von Nuklearversuchen (CTBTO)',
    'ann.a2.desc':  'Côte d\'Ivoire hat den Vorsitz der Vorbereitungskommission der Organisation des Vertrags über das umfassende Verbot von Nuklearversuchen (CTBTO) übernommen, ein bedeutender Meilenstein der ivorischen Diplomatie auf der internationalen Bühne in Wien.',
    'ann.a3.title': 'Zivile Kernkraft: Côte d\'Ivoire setzt sich für eine verstärkte Unterstützung der Internationalen Atomenergiebehörde (IAEA) ein',
    'ann.a3.desc':  'Côte d\'Ivoire hat bei den Arbeiten der IAEA in Wien ihren Wunsch geäußert, verstärkte Unterstützung für die Entwicklung ihres zivilen Atomprogramms zu erhalten.',
    'ann.a4.title': 'Ivorische Diplomatie in Österreich: Botschafter Cissé Yacouba trifft den Landeshauptmann von Vorarlberg',
    'ann.a4.desc':  'Seine Exzellenz Herr Cissé Yacouba, Botschafter von Côte d\'Ivoire in Österreich, hat den Landeshauptmann des Bundeslandes Vorarlberg im Rahmen der Stärkung der bilateralen Beziehungen zwischen Côte d\'Ivoire und Österreich getroffen.',
    'ann.a5.title': 'Offizielle Mitteilung — Überreichung der Beglaubigungsschreiben',
    'ann.a5.desc':  'Seine Exzellenz Herr Cissé Yacouba, Außerordentlicher und Bevollmächtigter Botschafter der Republik Côte d\'Ivoire, hat dem Bundespräsidenten der Republik Österreich sein Beglaubigungsschreiben bei einer offiziellen Zeremonie im Hofburg-Palast in Wien überreicht.',
    'ann.a6.title': "Côte d'Ivoire und CTBTO besiegeln in Abidjan eine Partnerschaft im Bereich nuklearer Sicherheit",
    'ann.a6.desc':  "Am 26. Juni 2026 unterzeichneten die Côte d'Ivoire und die Organisation des Vertrags über das umfassende Verbot von Nuklearversuchen (CTBTO) in Abidjan ein Partnerschaftsabkommen zur Stärkung des Internationalen Überwachungssystems (IMS). Botschafter Cissé Yacouba vertrat die ivorische Delegation gemeinsam mit Außenministerin Nialé Kaba und Exekutivsekretär Robert Floyd.",
    'ann.a6.date':  "26. Juni 2026",
