    'psrv.faq.q1': 'Is an appointment absolutely required?',
    'psrv.faq.a1': 'Yes, booking an appointment is mandatory for all file submissions. No file will be accepted without a prior appointment. You can book by phone or email.',
    'psrv.faq.q2': 'How long does passport processing take?',
    'psrv.faq.a2': 'The average processing time for a biometric passport is 4 to 8 weeks. This depends on processing conditions in Abidjan. In duly justified emergencies, an emergency passport can be issued within 24 to 72 hours.',
    'psrv.faq.q3': 'Are fees refundable in case of refusal?',
    'psrv.faq.a3': 'No, consular fees are non-refundable, including in cases of application refusal. It is therefore important to ensure your file is complete before submitting it.',
    'psrv.faq.q4': 'Can I send my file by post?',
    'psrv.faq.a4': 'For certain simple requests (legalisation of copies, some certificates), sending by registered post is possible. For passport and national ID card applications, the physical presence of the applicant is mandatory for biometric data capture.',
    'psrv.faq.q5': 'I live in Hungary — can I handle my affairs in Vienna?',
    'psrv.faq.a5': "Yes, the Embassy of Côte d'Ivoire in Vienna is competent for all Ivorian nationals residing in Austria, Hungary, Slovenia, Slovakia, Croatia, Serbia, Romania and Bosnia-Herzegovina. You must travel to Vienna to carry out your procedures.",
