    'pamb.ci.p1':   "The Republic of Côte d'Ivoire is a West African country bordered to the south by the Gulf of Guinea. The largest economy in the West African Economic and Monetary Union (UEMOA), it is the world's leading cocoa producer.",
    'pamb.ci.p2':   "Abidjan, the economic capital, is one of the most dynamic metropolises in sub-Saharan Africa. Yamoussoukro is the political and administrative capital of the country.",
