    'ann.pinned.desc':     'The Embassy of Côte d\'Ivoire in Vienna will be <strong>closed on Friday, August 7, 2026</strong> on the occasion of the National Day of the Republic of Côte d\'Ivoire (66th anniversary of independence). Services will resume normally on Monday, August 10, 2026 at 09:30.',
