    'ann.a4.title':'Ivóri diplomácia Ausztriában: Cissé Yacouba nagykövet találkozik Vorarlberg tartományi kormányzójával','ann.a4.desc':'Ő Excellenciája Cissé Yacouba úr, Elefántcsontpart ausztriai nagykövete, találkozott Vorarlberg tartomány kormányzójával az Elefántcsontpart és Ausztria közötti kétoldalú kapcsolatok erősítése keretében.',
    'ann.a5.title':'Hivatalos közlemény — Megbízólevelek átadása','ann.a5.desc':'Ő Excellenciája Cissé Yacouba úr, az Elefántcsontparti Köztársaság rendkívüli és meghatalmazott nagykövete, átadta megbízólevelét az Osztrák Köztársaság szövetségi elnökének egy hivatalos ünnepségen a bécsi Hofburg-palotában.',
    'ann.a6.title':'Elefántcsontpart és a CTBTO Abidjanban partnerségi megállapodást kötött a nukleáris biztonság területén','ann.a6.desc':'2026. június 26-án, Abidjanban, Elefántcsontpart és az Átfogó Atomcsend-egyezmény Szervezete (CTBTO) partnerségi megállapodást írt alá a Nemzetközi Megfigyelő Rendszer (IMS) megerősítése céljából. Cissé Yacouba nagykövet képviselte az ivóri küldöttséget Nialé Kaba külügyminiszter és Robert Floyd ügyvezető titkár mellett.','ann.a6.date':'2026. június 26.',
