    'cc.title':'Konzuli igazolvány','cc.eligibility.title':'Jogosultsági feltételek','cc.eligibility.text':'Elefántcsontparti állampolgárság, aki a nagykövetség diplomáciai illetékességi területén él (Ausztria, Magyarország, Horvátország, Szerbia, Szlovákia, Szlovénia, Románia, Bosznia-Hercegovina, Moldova).',
    'cc.docs.title':'Benyújtandó dokumentumok','cc.docs.li1':'1 db színes útlevélkép fehér háttérrel','cc.docs.li2':'Az útlevél első 3 oldalának fénymásolata','cc.docs.li3':'Személyazonosító okmány másolata (SZIG, állampolgársági bizonyítvány)','cc.docs.li4':'Tartózkodási engedély','cc.docs.li5':'A születési anyakönyvi kivonat fénymásolata',
