    'cc.f.nom':'Vezetéknév','cc.f.prenom':'Keresztnév','cc.f.naissance':'Születési dátum','cc.f.adresse':'Cím','cc.f.email':'E-mail',
    'cc.docs.email.note':'A formanyomtatvány elküldése után kérjük, küldje el a fenti dokumentumok másolatát e-mailben a <strong>sceconsul.autriche@diplomatie.gouv.ci</strong> címre, tárgyként megadva vezeték- és keresztnevét.',
    'cc.f.submit':'Kérelem elküldése →','cc.status.sending':'Küldés folyamatban…','cc.status.success':'✓ A kérelmet sikeresen elküldtük!','cc.status.error':'Hiba történt a küldés során. Kérjük, próbálja újra, vagy vegye fel velünk közvetlenül a kapcsolatot.',
    'psrv.faq.q1':'Feltétlenül szükséges az időpontfoglalás?','psrv.faq.a1':'Igen, az időpontfoglalás kötelező minden dossziébenyújtáshoz. Előzetes időpont nélkül semmilyen dossziét nem fogadunk el. Időpontot telefonon vagy e-mailben foglalhat.',
    'psrv.faq.q2':'Mennyi ideig tart egy útlevél feldolgozása?','psrv.faq.a2':'A biometrikus útlevél átlagos feldolgozási ideje 4-8 hét. Ez az időtartam az abidjani feldolgozási körülményektől függ. Kellően igazolt sürgősség esetén sürgősségi útlevél 24-72 órán belül kiállítható.',
    'psrv.faq.q3':'Elutasítás esetén visszatérítik a díjakat?','psrv.faq.a3':'Nem, a konzuli díjak nem visszatéríthetők, még a kérelem elutasítása esetén sem. Ezért fontos, hogy a benyújtás előtt győződjön meg dossziéja teljességéről.',
    'psrv.faq.q4':'Elküldhetem dossziémat postai úton?','psrv.faq.a4':'Egyes egyszerű kérelmek esetén (másolatok hitelesítése, bizonyos igazolások) az ajánlott postai küldés lehetséges. Útlevél- és személyiigazolvány-igénylés esetén a kérelmező személyes megjelenése kötelező a biometrikus ujjlenyomat-vétel miatt.',
    'psrv.faq.q5':'Magyarországon élek, intézhetem ügyeimet Bécsben?','psrv.faq.a5':'Igen, az Elefántcsontparti Nagykövetség Bécsben illetékes valamennyi Ausztriában, Magyarországon, Szlovéniában, Szlovákiában, Horvátországban, Szerbiában, Romániában és Bosznia-Hercegovinában élő elefántcsontparti állampolgár számára. Ügyeinek intézéséhez Bécsbe kell utaznia.',
    'pcon.h1':'Kapcsolat és nyitvatartás','pcon.desc':'A konzuli szolgálat teljes elérhetősége és nyitvatartási ideje. Minden ügyintézéshez előzetes időpontfoglalás szükséges.',
    'pcon.tel.lbl':'Telefon','pcon.email.lbl':'Konzuli e-mail','pcon.addr.lbl':'Cím','pcon.urg.lbl':'Konzuli sürgősségi ügyek','pcon.urg.sub':'Sürgősségi esetekben 0–24 órában elérhető',
