    'pcon.v1.tag':'Autóval vagy taxival','pcon.v1.rec':'Ajánlott','pcon.v1.desc':'Az autóval vagy taxival történő érkezés a legegyszerűbb módja a nagykövetség elérésének. Közvetlenül az épület elé érkezik. Vegye a liftet a 3. emeletre, majd induljon a 332-333-as ajtók felé.',
    'pcon.v2.tag':'Metróval (U4 Heiligenstadt)','pcon.v2.rec':'Gyors és praktikus','pcon.v2.desc':'A Heiligenstadt (U4) állomástól menjen fel a mozgólépcsőn a Leopold-Ungar-Platz 2-ig, majd haladjon egyenesen tovább. Vegye a 3. lépcsőházat, menjen fel a 3. emeletre, 332-333-as ajtó.',
