    'cc.docs.email.note':'Po oddaji tega obrazca vas prosimo, da po e-pošti pošljete kopijo vseh zgoraj navedenih dokumentov na naslov <strong>sceconsul.autriche@diplomatie.gouv.ci</strong>, pri čemer v zadevo navedite svoje ime in priimek.',
    'cc.f.submit':'Pošlji vlogo →','cc.status.sending':'Pošiljanje …','cc.status.success':'✓ Vloga je bila uspešno poslana!','cc.status.error':'Napaka pri pošiljanju. Poskusite znova ali nas kontaktirajte neposredno.',
    'psrv.faq.q1':'Ali je sestanek res nujen?','psrv.faq.a1':'Da, najava sestanka je obvezna za vsako oddajo dokumentacije. Brez predhodnega sestanka ne sprejmemo nobene dokumentacije. Sestanek lahko naročite po telefonu ali e-pošti.',
    'psrv.faq.q2':'Koliko časa traja obravnava potnega lista?','psrv.faq.a2':'Povprečen rok obravnave biometričnega potnega lista je 4 do 8 tednov. Ta rok je odvisen od pogojev obravnave v Abidjanu. V primeru ustrezno utemeljene nujnosti se lahko nujni potni list izda v 24 do 72 urah.',
    'psrv.faq.q3':'Ali se pristojbine vrnejo v primeru zavrnitve?','psrv.faq.a3':'Ne, konzularne pristojbine niso povračljive, tudi v primeru zavrnitve vloge. Zato je pomembno, da pred oddajo preverite popolnost svoje dokumentacije.',
    'psrv.faq.q4':'Ali lahko dokumentacijo pošljem po pošti?','psrv.faq.a4':'Za nekatere preproste vloge (overitev kopij, določena potrdila) je pošiljanje s priporočeno pošto mogoče. Za vloge za potni list in osebno izkaznico je zaradi biometričnega odvzema prstnih odtisov obvezna osebna navzočnost vlagatelja.',
    'psrv.faq.q5':'Živim na Madžarskem, ali lahko postopke opravim na Dunaju?','psrv.faq.a5':'Da, Veleposlaništvo Slonokoščene obale na Dunaju je pristojno za vse državljane Slonokoščene obale s prebivališčem v Avstriji, na Madžarskem, v Sloveniji, na Slovaškem, Hrvaškem, v Srbiji, Romuniji in Bosni in Hercegovini. Za opravljanje postopkov se morate zglasiti na Dunaju.',
    'pcon.h1':'Kontakt in uradne ure','pcon.desc':'Popolni kontaktni podatki in uradne ure konzularne službe. Za vsak postopek je potreben predhodni sestanek.',
