    'pcon.v.badge':'Video navodila','pcon.v.title':'Kako priti do nas','pcon.v.subtitle':'Oglejte si naše video vodnike, kako enostavno priti do veleposlaništva z različnih izhodišč.',
    'pcon.v1.tag':'Z avtomobilom ali taksijem','pcon.v1.rec':'Priporočeno','pcon.v1.desc':'Prihod z avtomobilom ali taksijem je najbolj neposreden način za dosego veleposlaništva. Pripeljete se neposredno pred stavbo. Z dvigalom se odpeljite v 3. nadstropje in se usmerite proti vratom 332-333.',
    'pcon.v2.tag':'S podzemno (U4 Heiligenstadt)','pcon.v2.rec':'Hitro in praktično','pcon.v2.desc':'S postaje Heiligenstadt (U4) se z gibljivimi stopnicami povzpnite do Leopold-Ungar-Platz 2 in nadaljujte naravnost. Uporabite stopnišče 3, pojdite v 3. nadstropje, vrata 332-333.',
