    'pamb.h1':'Veleposlaništvo Slonokoščene obale','pamb.desc':'Uradno predstavništvo Republike Slonokoščene obale v Avstriji s sedežem na Dunaju, ki zagotavlja diplomatske odnose in konzularne storitve za 9 držav srednje Evrope.',
    'pamb.mis.badge':'Naše poslanstvo','pamb.mis.title':'Diplomatsko in konzularno poslanstvo',
    'pamb.pays.badge':'Pristojnost','pamb.pays.title':'Diplomatsko območje','pamb.pays.sub':'Veleposlaništvo Slonokoščene obale na Dunaju pokriva diplomatsko območje naslednjih 9 držav.',
    'pamb.amb.badge':'Vodstvo',
    'pamb.rel.badge':'Diplomacija','pamb.rel.title':'Odnosi Slonokoščena obala — Avstrija',
    'pamb.ci.badge':'Slonokoščena obala','pamb.ci.title':'Odkrijte Slonokoščeno obalo',
    'pamb.ci.p1':'Republika Slonokoščena obala je zahodnoafriška država, na jugu mejijo na Gvinejski zaliv. Kot največje gospodarstvo Zahodnoafriške gospodarske in monetarne unije (UEMOA) je največji svetovni proizvajalec kakava.',
    'pamb.ci.p2':'Abidjan, gospodarska prestolnica, je ena najbolj dinamičnih metropol podsaharske Afrike. Yamoussoukro je politična in upravna prestolnica države.',
    'pamb.ci.stat.area':'Površina','pamb.ci.stat.pop':'Prebivalstvo','pamb.ci.stat.lang':'Uradni jezik','pamb.ci.stat.lang.val':'Francoščina','pamb.ci.stat.currency':'Valuta','pamb.ci.stat.indep':'Neodvisnost','pamb.ci.stat.indep.val':'7. avgust 1960','pamb.ci.stat.capital':'Politična prestolnica',
    'pamb.ci.republic':'Republika Slonokoščena obala',
    'pamb.org.badge':'Veleposlaništvo','pamb.org.title':'Organigram',
    'pamb.org.p1':'Veleposlaništvo in Stalno predstavništvo je organizirano okoli Stalnega predstavnika in specializirane diplomatske ekipe, ki pokriva 9 srednjeevropskih držav.',
    'pamb.org.p2':'Struktura vključuje ministrske svetovalce, direktorico UNIDO, blagajnika, svetovalce, prve sekretarje ter upravno in tehnično osebje.',
    'pamb.org.btn':'Ogled organigrama →',
    'pamb.net.badge':'Zunanja mreža','pamb.net.title':'Slonokoščena diplomatska mreža po svetu','pamb.net.desc':'Veleposlaništva, generalni konzulati, stalne misije in delegacije po vsem svetu.',
    'pamb.net.amb':'Veleposlaništva','pamb.net.cg':'Generalni konzulati','pamb.net.mis':'Misije in delegacije','pamb.net.circ':'Območja pristojnosti','pamb.net.villes':'Mesta','pamb.net.pays':'Države gostiteljice',
    'net.filter.all':'Vsa mesta','net.filter.circ':'Območja pristojnosti','net.filter.arcs':'Povezave iz Abidjana',
    'net.search.ph':'Iščite mesto, državo…','net.hint':'Izberite točko na zemljevidu ali mesto s spodnjega seznama za prikaz podrobnosti.','net.close':'Svetovni pogled',
    'net.footer':'Veleposlaništvo = dvostransko predstavništvo pri državi · Generalni konzulat = konzularno mesto za določeno območje · Stalna misija = predstavništvo pri mednarodni organizaciji.',
    'badge.ci':'Slonokoščena obala','ci.title':'Odkrijte Slonokoščeno obalo','ci.republic':'Republika Slonokoščena obala',
    'ci.area':'Površina','ci.pop':'Prebivalstvo','ci.indep':'Neodvisnost','ci.indep.val':'7. avgust 1960','ci.capital':'Prestolnica',
    'pamb.mis.p1':'Veleposlaništvo Republike Slonokoščene obale v Avstriji je uradno diplomatsko predstavništvo Slonokoščene obale na Dunaju. Zagotavlja zaščito ivoirskih interesov, razvoj dvostranskih odnosov in zaščito svojih državljanov.',
    'pamb.mis.p2':'Ustanovljeno v skladu z Dunajsko konvencijo o diplomatskih odnosih iz leta 1961, Veleposlaništvo opravlja dvojno poslanstvo: diplomatsko (predstavljanje države pri državi gostiteljici) in konzularno (pomoč ivoirskim državljanom, ki prebivajo na njegovem območju pristojnosti).',
    'pamb.mis.p3':'V okviru svoje teritorialne pristojnosti Veleposlaništvo pokriva 9 držav: Avstrijo, Madžarsko, Slovenijo, Slovaško, Hrvaško, Srbijo, Romunijo in Bosno in Hercegovino.',
    'pamb.stat.countries':'držav v diplomatskem območju','pamb.stat.conv':'Dunajska konvencija','pamb.stat.ci':'Slonokoščena obala','pamb.stat.host':'Država gostiteljica',
    'pamb.amb.title':'Izredni in pooblaščeni veleposlanik Republike Slonokoščene obale v Avstriji',
    'pamb.amb.p1':'Njegova ekscelenca gospod Cissé Yacouba je akreditiran pri Republiki Avstriji kot izredni in pooblaščeni veleposlanik Republike Slonokoščene obale. Akreditiran je tudi pri Madžarski, Sloveniji, Slovaški, Hrvaški, Srbiji, Romuniji in Bosni in Hercegovini.',
    'pamb.amb.p2':'Z dolgo diplomatsko kariero v službi Slonokoščene obale Njegova ekscelenca gospod Cissé Yacouba zastopa interese ivoirske republike, spodbuja dvostranske in večstranske odnose ter usklajuje vse službe Veleposlaništva.',
    'porg.breadcrumb':'Organigram','porg.h1':'Organigram','porg.desc':'Organizacijska struktura Veleposlaništva in Stalnega predstavništva Slonokoščene obale na Dunaju.',
    'porg.motto':'REPUBLIKA SLONOKOŠČENA OBALA — ENOTNOST · DISCIPLINA · DELO',
