    'psrv.faq.q1':'Je stretnutie naozaj nevyhnutné?','psrv.faq.a1':'Áno, dohodnutie stretnutia je povinné pre každé podanie žiadosti. Bez predchádzajúceho stretnutia neprijmeme žiadnu žiadosť. Stretnutie si môžete dohodnúť telefonicky alebo e-mailom.',
    'psrv.faq.q2':'Ako dlho trvá vybavenie cestovného pasu?','psrv.faq.a2':'Priemerná lehota vybavenia biometrického cestovného pasu je 4 až 8 týždňov. Táto lehota závisí od podmienok spracovania v Abidžane. V prípade riadne odôvodnenej naliehavosti možno núdzový cestovný pas vydať do 24 až 72 hodín.',
    'psrv.faq.q3':'Vracajú sa poplatky v prípade zamietnutia?','psrv.faq.a3':'Nie, konzulárne poplatky sa nevracajú, a to ani v prípade zamietnutia žiadosti. Preto je dôležité pred podaním zabezpečiť úplnosť vašej dokumentácie.',
    'psrv.faq.q4':'Môžem svoju žiadosť poslať poštou?','psrv.faq.a4':'Pri niektorých jednoduchých žiadostiach (overenie kópií, niektoré potvrdenia) je možné zaslanie doporučenou poštou. Pri žiadostiach o cestovný pas a občiansky preukaz je fyzická prítomnosť žiadateľa povinná kvôli odberu biometrických odtlačkov.',
    'psrv.faq.q5':'Bývam v Maďarsku, môžem svoje úkony vybaviť vo Viedni?','psrv.faq.a5':'Áno, Veľvyslanectvo Pobrežia Slonoviny vo Viedni je príslušné pre všetkých občanov Pobrežia Slonoviny s pobytom v Rakúsku, Maďarsku, Slovinsku, na Slovensku, v Chorvátsku, Srbsku, Rumunsku a Bosne a Hercegovine. Na vybavenie úkonov sa musíte dostaviť do Viedne.',
    'pcon.h1':'Kontakt a úradné hodiny','pcon.desc':'Kompletné kontaktné údaje a úradné hodiny konzulárnej služby. Každý úkon vyžaduje predchádzajúce dohodnutie stretnutia.',
    'pcon.tel.lbl':'Telefón','pcon.email.lbl':'Konzulárny e-mail','pcon.addr.lbl':'Adresa','pcon.urg.lbl':'Konzulárne núdzové situácie','pcon.urg.sub':'K dispozícii 24 hodín denne pre núdzové situácie',
