    'pcon.f.badge':'Napíšte nám','pcon.f.title':'Kontaktný formulár','pcon.f.desc':'Pre akékoľvek otázky alebo žiadosť o stretnutie vyplňte tento formulár. Odpovieme vám do 3 až 5 pracovných dní.','pcon.f.send':'Odoslať správu →',
