    'pcon.v1.tag':'Autom alebo taxíkom','pcon.v1.rec':'Odporúčané','pcon.v1.desc':'Príchod autom alebo taxíkom je najpriamejší spôsob, ako sa dostať na veľvyslanectvo. Prídete priamo pred budovu. Použite výťah na 3. poschodie a zamierte k dverám 332-333.',
    'pcon.v2.tag':'Metrom (U4 Heiligenstadt)','pcon.v2.rec':'Rýchle a praktické','pcon.v2.desc':'Zo stanice Heiligenstadt (U4) choďte po eskalátore na Leopold-Ungar-Platz 2 a pokračujte rovno. Použite schodisko 3, choďte na 3. poschodie, dvere 332-333.',
