    'pamb.h1':'Veľvyslanectvo Pobrežia Slonoviny','pamb.desc':'Oficiálne zastúpenie Republiky Pobrežia Slonoviny v Rakúsku so sídlom vo Viedni, ktoré zabezpečuje diplomatické vzťahy a konzulárne služby pre 9 krajín strednej Európy.',
    'pamb.mis.badge':'Naše poslanie','pamb.mis.title':'Diplomatické a konzulárne poslanie',
    'pamb.pays.badge':'Pôsobnosť','pamb.pays.title':'Diplomatický obvod','pamb.pays.sub':'Veľvyslanectvo Pobrežia Slonoviny vo Viedni pokrýva diplomatický obvod nasledujúcich 9 krajín.',
