    'net.search.ph':'Hľadajte mesto, krajinu…','net.hint':'Vyberte bod na mape alebo zastúpenie zo zoznamu nižšie na zobrazenie podrobností.','net.close':'Svetový pohľad',
    'net.footer':'Veľvyslanectvo = bilaterálne zastúpenie pri štáte · Generálny konzulát = konzulárne miesto pre obvod · Stála misia = zastúpenie pri medzinárodnej organizácii.',
    'badge.ci':'Pobrežie Slonoviny','ci.title':'Objavte Pobrežie Slonoviny','ci.republic':'Republika Pobrežia Slonoviny',
    'ci.area':'Rozloha','ci.pop':'Obyvateľstvo','ci.indep':'Nezávislosť','ci.indep.val':'7. augusta 1960','ci.capital':'Hlavné mesto',
    'pamb.mis.p1':'Veľvyslanectvo Republiky Pobrežia Slonoviny v Rakúsku je oficiálnym diplomatickým zastúpením Pobrežia Slonoviny vo Viedni. Zabezpečuje obranu pobrežnoslonovinských záujmov, rozvoj bilaterálnych vzťahov a ochranu svojich občanov.',
    'pamb.mis.p2':'Zriadené v súlade s Viedenským dohovorom o diplomatických stykoch z roku 1961, Veľvyslanectvo plní dvojaké poslanie: diplomatické (zastupovanie štátu pri hostiteľskej krajine) a konzulárne (pomoc pobrežnoslonovinským občanom s pobytom v jeho obvode).',
    'pamb.mis.p3':'V rámci svojej územnej pôsobnosti Veľvyslanectvo pokrýva 9 krajín: Rakúsko, Maďarsko, Slovinsko, Slovensko, Chorvátsko, Srbsko, Rumunsko a Bosnu a Hercegovinu.',
    'pamb.stat.countries':'krajín v diplomatickom obvode','pamb.stat.conv':'Viedenský dohovor','pamb.stat.ci':'Pobrežie Slonoviny','pamb.stat.host':'Hostiteľská krajina',
    'pamb.amb.title':'Mimoriadny a splnomocnený veľvyslanec Republiky Pobrežia Slonoviny v Rakúsku',
    'pamb.amb.p1':'Jeho Excelencia pán Cissé Yacouba je akreditovaný pri Rakúskej republike ako mimoriadny a splnomocnený veľvyslanec Republiky Pobrežia Slonoviny. Je tiež akreditovaný pri Maďarsku, Slovinsku, Slovensku, Chorvátsku, Srbsku, Rumunsku a Bosne a Hercegovine.',
    'pamb.amb.p2':'S bohatou diplomatickou kariérou v službách Pobrežia Slonoviny Jeho Excelencia pán Cissé Yacouba zastupuje záujmy pobrežnoslonovinskej republiky, podporuje bilaterálne a multilaterálne vzťahy a koordinuje všetky služby Veľvyslanectva.',
    'porg.breadcrumb':'Organizačná štruktúra','porg.h1':'Organizačná štruktúra','porg.desc':'Organizačná štruktúra Veľvyslanectva a Stáleho zastúpenia Pobrežia Slonoviny vo Viedni.',
