    'ann.pinned.label':'Zakvačeno — Hitno','ann.pinned.title':'Izvanredno zatvaranje — Državni praznik Obale Bjelokosti','ann.pinned.desc':'Veleposlanstvo Obale Bjelokosti u Beču bit će <strong>zatvoreno u petak, 7. kolovoza 2026.</strong>, povodom Državnog praznika Republike Obale Bjelokosti (66. obljetnica neovisnosti). Usluge će se redovito nastaviti u ponedjeljak, 10. kolovoza 2026., u 09.30.','ann.pinned.date':'Objavljeno 25. svibnja 2026.',
