    'ann.a1.title':'Gospodarska misija: Aka Aouélé vodi izaslanstvo Gospodarskog, socijalnog, okolišnog i kulturnog vijeća (CESEC) u Austriju','ann.a1.desc':'Predsjednik CESEC-a, Aka Aouélé, vodio je izaslanstvo Obale Bjelokosti u Austriju u sklopu gospodarske misije usmjerene na jačanje razmjena i suradnje između Obale Bjelokosti i njezinih europskih partnera.',
    'ann.a2.title':'Diplomacija Obale Bjelokosti u središtu pozornosti u Beču: Obala Bjelokosti preuzima predsjedanje Organizacijom Ugovora o sveobuhvatnoj zabrani nuklearnih pokusa','ann.a2.desc':'Obala Bjelokosti preuzela je predsjedanje Pripremnim povjerenstvom Organizacije Ugovora o sveobuhvatnoj zabrani nuklearnih pokusa (CTBTO), što označava važan iskorak diplomacije Obale Bjelokosti na međunarodnoj sceni u Beču.',
    'ann.a3.title':'Civilna nuklearna energija: Obala Bjelokosti zagovara jaču potporu Međunarodne agencije za atomsku energiju','ann.a3.desc':'Obala Bjelokosti izrazila je u Beču, tijekom rada IAEA-e, želju za pojačanom potporom u razvoju svog civilnog nuklearnog programa.',
    'ann.a4.title':'Diplomacija Obale Bjelokosti u Austriji: veleposlanik Cissé Yacouba razgovarao s guvernerom Vorarlberga','ann.a4.desc':'Njegova Ekscelencija gospodin Cissé Yacouba, veleposlanik Obale Bjelokosti u Austriji, sastao se s guvernerom savezne pokrajine Vorarlberg u sklopu jačanja bilateralnih odnosa između Obale Bjelokosti i Austrije.',
    'ann.a5.title':'Službeno priopćenje — Predaja vjerodajnica','ann.a5.desc':'Njegova Ekscelencija gospodin Cissé Yacouba, izvanredni i opunomoćeni veleposlanik Republike Obale Bjelokosti, predao je svoje vjerodajnice saveznom predsjedniku Republike Austrije na službenoj svečanosti u palači Hofburg u Beču.',
    'ann.a6.title':'Obala Bjelokosti i CTBTO sklopile su u Abidjanu partnerstvo na području nuklearne sigurnosti','ann.a6.desc':'26. lipnja 2026. u Abidjanu su Obala Bjelokosti i Organizacija Ugovora o sveobuhvatnoj zabrani nuklearnih pokusa (CTBTO) potpisale sporazum o partnerstvu usmjeren na jačanje Međunarodnog sustava nadzora (IMS). Veleposlanik Cissé Yacouba predstavljao je izaslanstvo Obale Bjelokosti uz ministricu vanjskih poslova Nialé Kabu i izvršnog tajnika Roberta Floyda.','ann.a6.date':'26. lipnja 2026.',
