    'cc.docs.email.note':'Nakon slanja ovog obrasca, molimo pošaljite kopiju svih gore navedenih dokumenata e-poštom na <strong>sceconsul.autriche@diplomatie.gouv.ci</strong>, navodeći svoje ime i prezime u predmetu.',
    'cc.f.submit':'Pošalji zahtjev →','cc.status.sending':'Slanje u tijeku…','cc.status.success':'✓ Zahtjev je uspješno poslan!','cc.status.error':'Pogreška prilikom slanja. Pokušajte ponovno ili nas kontaktirajte izravno.',
    'psrv.faq.q1':'Je li sastanak doista neophodan?','psrv.faq.a1':'Da, zakazivanje sastanka obvezno je za svako podnošenje dokumentacije. Bez prethodnog sastanka nijedna dokumentacija neće biti prihvaćena. Sastanak možete zakazati telefonom ili e-poštom.',
    'psrv.faq.q2':'Koliko traje obrada putovnice?','psrv.faq.a2':'Prosječni rok obrade biometrijske putovnice iznosi 4 do 8 tjedana. Taj rok ovisi o uvjetima obrade u Abidjanu. U slučaju propisno opravdane hitnosti, hitna putovnica može se izdati u roku od 24 do 72 sata.',
    'psrv.faq.q3':'Vraćaju li se pristojbe u slučaju odbijanja?','psrv.faq.a3':'Ne, konzularne pristojbe nisu povratne, čak ni u slučaju odbijanja zahtjeva. Stoga je važno prije podnošenja provjeriti je li vaša dokumentacija potpuna.',
    'psrv.faq.q4':'Mogu li poslati svoju dokumentaciju poštom?','psrv.faq.a4':'Za neke jednostavne zahtjeve (ovjera preslika, određene potvrde) moguće je slanje preporučenom poštom. Za zahtjeve za putovnicu i osobnu iskaznicu obvezna je osobna nazočnost podnositelja zahtjeva radi uzimanja biometrijskih otisaka.',
    'psrv.faq.q5':'Živim u Mađarskoj, mogu li svoje postupke obaviti u Beču?','psrv.faq.a5':'Da, Veleposlanstvo Obale Bjelokosti u Beču nadležno je za sve državljane Obale Bjelokosti s prebivalištem u Austriji, Mađarskoj, Sloveniji, Slovačkoj, Hrvatskoj, Srbiji, Rumunjskoj i Bosni i Hercegovini. Za obavljanje postupaka morate doći u Beč.',
    'pcon.h1':'Kontakt i radno vrijeme','pcon.desc':'Potpuni kontaktni podaci i radno vrijeme konzularne službe. Svaki postupak zahtijeva prethodno zakazan sastanak.',
