    'pamb.ci.p1':'Republika Obala Bjelokosti zapadnoafrička je zemlja, na jugu graniči s Gvinejskim zaljevom. Kao najveće gospodarstvo Zapadnoafričke gospodarske i monetarne unije (UEMOA), najveći je svjetski proizvođač kakaa.',
    'pamb.ci.p2':'Abidjan, gospodarska prijestolnica, jedna je od najdinamičnijih metropola subsaharske Afrike. Yamoussoukro je politička i administrativna prijestolnica zemlje.',
    'pamb.ci.stat.area':'Površina','pamb.ci.stat.pop':'Stanovništvo','pamb.ci.stat.lang':'Službeni jezik','pamb.ci.stat.lang.val':'Francuski','pamb.ci.stat.currency':'Valuta','pamb.ci.stat.indep':'Neovisnost','pamb.ci.stat.indep.val':'7. kolovoza 1960.','pamb.ci.stat.capital':'Politička prijestolnica',
