    'pamb.org.p1':'Veleposlanstvo i Stalno predstavništvo organizirani su oko Stalnog predstavnika i specijaliziranog diplomatskog tima koji pokriva 9 zemalja srednje Europe.',
    'pamb.org.p2':'Struktura obuhvaća ministre savjetnike, direktoricu UNIDO-a, blagajnika, savjetnike, prve tajnike te administrativno i tehničko osoblje.',
