    'net.footer':'Veleposlanstvo = bilateralno predstavništvo pri državi · Generalni konzulat = konzularno mjesto za područje · Stalna misija = predstavništvo pri međunarodnoj organizaciji.',
    'badge.ci':'Obala Bjelokosti','ci.title':'Otkrijte Obalu Bjelokosti','ci.republic':'Republika Obala Bjelokosti',
