    'pamb.mis.p1':'Veleposlanstvo Republike Obale Bjelokosti u Austriji službeno je diplomatsko predstavništvo Obale Bjelokosti u Beču. Osigurava obranu interesa Obale Bjelokosti, razvoj bilateralnih odnosa i zaštitu svojih državljana.',
    'pamb.mis.p2':'Osnovano u skladu s Bečkom konvencijom o diplomatskim odnosima iz 1961., Veleposlanstvo ispunjava dvostruko poslanje: diplomatsko (predstavljanje države pri državi domaćinu) i konzularno (pomoć državljanima Obale Bjelokosti s prebivalištem u njegovoj nadležnosti).',
    'pamb.mis.p3':'U okviru svoje teritorijalne nadležnosti Veleposlanstvo pokriva 9 zemalja: Austriju, Mađarsku, Sloveniju, Slovačku, Hrvatsku, Srbiju, Rumunjsku i Bosnu i Hercegovinu.',
    'pamb.stat.countries':'zemalja u diplomatskom području','pamb.stat.conv':'Bečka konvencija','pamb.stat.ci':'Obala Bjelokosti','pamb.stat.host':'Zemlja domaćin',
    'pamb.amb.title':'Izvanredni i opunomoćeni veleposlanik Republike Obale Bjelokosti u Austriji',
    'pamb.amb.p1':'Njegova Ekscelencija gospodin Cissé Yacouba akreditiran je pri Republici Austriji kao izvanredni i opunomoćeni veleposlanik Republike Obale Bjelokosti. Također je akreditiran pri Mađarskoj, Sloveniji, Slovačkoj, Hrvatskoj, Srbiji, Rumunjskoj i Bosni i Hercegovini.',
    'pamb.amb.p2':'S dugom diplomatskom karijerom u službi Obale Bjelokosti, Njegova Ekscelencija gospodin Cissé Yacouba zastupa interese republike Obale Bjelokosti, promiče bilateralne i multilateralne odnose te koordinira sve službe Veleposlanstva.',
