    'dl.f02.eyebrow':'Registracija','dl.f02.title':'Konzularni obrazac za registraciju','dl.f02.sub':'Upis u registar državljana Obale Slonovače u inostranstvu','dl.f02.desc':'Obavezno za sve državljane Obale Slonovače sa prebivalištem u Austriji. Registracija olakšava pristup konzularnim uslugama i štiti vaša prava u inostranstvu.','dl.f02.size':'PDF · 124 KB',
    'dl.f03.eyebrow':'Maloletnik','dl.f03.title':'Roditeljska izjava','dl.f03.sub':'Saglasnost za pasoš i/ili izvod iz matične knjige rođenih maloletnika','dl.f03.desc':'Saglasnost koju izdaje jedan ili oba roditelja za izdavanje pasoša ili izvoda iz matične knjige rođenih za maloletno dete. Potreban je overen potpis.','dl.f03.size':'PDF · 100 KB',
