    'dl.f05.eyebrow':'Matične knjige','dl.f05.title':'Prepis izvoda iz matične knjige rođenih','dl.f05.sub':'Deca rođena u inostranstvu od roditelja sa Obale Slonovače','dl.f05.desc':'Obrazac za upis stranog izvoda iz matične knjige rođenih u matične knjige Obale Slonovače. Obavezno za sticanje državljanstva i pasoša.','dl.f05.size':'PDF · 131 KB',
