    'dl.f07.eyebrow':'Overa','dl.f07.title':'Zahtev za overu','dl.f07.sub':'Overa administrativnih ili javnobeležničkih dokumenata','dl.f07.desc':'Obrazac za overu dokumenata Obale Slonovače ili stranih dokumenata namenjenih upotrebi na Obali Slonovače ili u trećoj zemlji. Primenjuje se na javnobeležničke, administrativne i komercijalne isprave.','dl.f07.size':'PDF · 121 KB',
    'dl.f08.eyebrow':'Putni list','dl.f08.title':'Zahtev za putni list','dl.f08.sub':'Privremena putna isprava u hitnim slučajevima','dl.f08.desc':'Privremena putna isprava izdata u slučaju gubitka, krađe ili isteka pasoša. Važi za putovanje u jednom pravcu za Obalu Slonovače.','dl.f08.size':'PDF · 139 KB',
