    'ann.h1':'Informacije i obaveštenja','ann.desc':'Ovde pronađite sve zvanične informacije, važna obaveštenja i saopštenja Ambasade Obale Slonovače u Beču.',
    'ann.pinned.label':'Zakačeno — Hitno','ann.pinned.title':'Vanredno zatvaranje — Državni praznik Obale Slonovače','ann.pinned.desc':'Ambasada Obale Slonovače u Beču biće <strong>zatvorena u petak, 7. avgusta 2026.</strong>, povodom Državnog praznika Republike Obale Slonovače (66. godišnjica nezavisnosti). Usluge će se redovno nastaviti u ponedeljak, 10. avgusta 2026, u 09.30.','ann.pinned.date':'Objavljeno 25. maja 2026.',
    'ann.filter.all':'Sve','ann.filter.urgent':'Hitno','ann.filter.admin':'Administrativno','ann.filter.event':'Događaji','ann.filter.communique':'Saopštenja',
    'ann.cat.mission':'Ekonomska misija','ann.cat.diplo':'Diplomatija','ann.cat.actu':'Vesti','ann.cat.communique':'Saopštenje',
    'ann.btn.read':' Pročitaj članak','ann.btn.readfull':' Pročitaj celo saopštenje','ann.empty':'Trenutno nema obaveštenja u ovoj kategoriji.',
    'ann.sidebar.links':'Korisni linkovi','ann.sidebar.passport':'Obnova pasoša','ann.sidebar.visa':'Zahtev za vizu','ann.sidebar.civil':'Matične knjige','ann.sidebar.rdv':'Zakažite termin','ann.sidebar.hours':'Radno vreme','ann.sidebar.contact':'Direktan kontakt',
    'ann.sub.title':'Primajte obaveštenja','ann.sub.desc':'Prijavite se da biste bili obavešteni o novim obaveštenjima i važnim informacijama.','ann.sub.btn':'Prijava na obaveštenja',
    'ann.a1.title':'Ekonomska misija: Aka Aouélé predvodi delegaciju Ekonomskog, socijalnog, ekološkog i kulturnog saveta (CESEC) u Austriju','ann.a1.desc':'Predsednik CESEC-a, Aka Aouélé, predvodio je delegaciju Obale Slonovače u Austriju u okviru ekonomske misije usmerene na jačanje razmena i saradnje između Obale Slonovače i njenih evropskih partnera.',
    'ann.a2.title':'Diplomatija Obale Slonovače u fokusu u Beču: Obala Slonovače preuzima predsedavanje Organizacijom Ugovora o sveobuhvatnoj zabrani nuklearnih proba','ann.a2.desc':'Obala Slonovače preuzela je predsedavanje Pripremnom komisijom Organizacije Ugovora o sveobuhvatnoj zabrani nuklearnih proba (CTBTO), što predstavlja važnu prekretnicu diplomatije Obale Slonovače na međunarodnoj sceni u Beču.',
    'ann.a3.title':'Civilna nuklearna energija: Obala Slonovače zagovara jaču podršku Međunarodne agencije za atomsku energiju','ann.a3.desc':'Obala Slonovače je u Beču, tokom rada IAEA, izrazila želju za pojačanom podrškom u razvoju svog civilnog nuklearnog programa.',
    'ann.a4.title':'Diplomatija Obale Slonovače u Austriji: ambasador Cissé Yacouba razgovarao sa guvernerom Forarlberga','ann.a4.desc':'Njegova Ekselencija gospodin Cissé Yacouba, ambasador Obale Slonovače u Austriji, sastao se sa guvernerom savezne pokrajine Forarlberg u okviru jačanja bilateralnih odnosa između Obale Slonovače i Austrije.',
    'ann.a5.title':'Zvanično saopštenje — Predaja akreditiva','ann.a5.desc':'Njegova Ekselencija gospodin Cissé Yacouba, izvanredni i opunomoćeni ambasador Republike Obale Slonovače, predao je svoja akreditivna pisma saveznom predsedniku Republike Austrije na zvaničnoj svečanosti u palati Hofburg u Beču.',
    'ann.a6.title':'Obala Slonovače i CTBTO sklopile su u Abidžanu partnerstvo u oblasti nuklearne bezbednosti','ann.a6.desc':'26. juna 2026. u Abidžanu su Obala Slonovače i Organizacija Ugovora o sveobuhvatnoj zabrani nuklearnih proba (CTBTO) potpisale sporazum o partnerstvu usmeren na jačanje Međunarodnog sistema nadzora (IMS). Ambasador Cissé Yacouba predstavljao je delegaciju Obale Slonovače zajedno sa ministarkom spoljnih poslova Nialé Kaba i izvršnim sekretarom Robertom Flojdom.','ann.a6.date':'26. jun 2026.',
