    'cc.docs.email.note':'Nakon slanja ovog obrasca, molimo pošaljite kopiju svih gore navedenih dokumenata imejlom na <strong>sceconsul.autriche@diplomatie.gouv.ci</strong>, navodeći svoje ime i prezime u naslovu.',
    'cc.f.submit':'Pošalji zahtev →','cc.status.sending':'Slanje u toku…','cc.status.success':'✓ Zahtev je uspešno poslat!','cc.status.error':'Greška prilikom slanja. Pokušajte ponovo ili nas kontaktirajte direktno.',
    'psrv.faq.q1':'Da li je termin zaista neophodan?','psrv.faq.a1':'Da, zakazivanje termina obavezno je za svako podnošenje dokumentacije. Bez prethodnog termina, nijedna dokumentacija neće biti prihvaćena. Termin možete zakazati telefonom ili imejlom.',
    'psrv.faq.q2':'Koliko traje obrada pasoša?','psrv.faq.a2':'Prosečan rok obrade biometrijskog pasoša je 4 do 8 nedelja. Ovaj rok zavisi od uslova obrade u Abidžanu. U slučaju propisno opravdane hitnosti, hitni pasoš može biti izdat u roku od 24 do 72 sata.',
    'psrv.faq.q3':'Da li se takse vraćaju u slučaju odbijanja?','psrv.faq.a3':'Ne, konzularne takse se ne vraćaju, čak ni u slučaju odbijanja zahteva. Zato je važno da pre podnošenja proverite da li je vaša dokumentacija kompletna.',
    'psrv.faq.q4':'Mogu li poslati svoju dokumentaciju poštom?','psrv.faq.a4':'Za pojedine jednostavne zahteve (overa kopija, određena uverenja) moguće je slanje preporučenom poštom. Za zahteve za pasoš i ličnu kartu obavezno je lično prisustvo podnosioca zahteva radi uzimanja biometrijskih otisaka.',
    'psrv.faq.q5':'Živim u Mađarskoj, mogu li svoje postupke da obavim u Beču?','psrv.faq.a5':'Da, Ambasada Obale Slonovače u Beču nadležna je za sve državljane Obale Slonovače sa prebivalištem u Austriji, Mađarskoj, Sloveniji, Slovačkoj, Hrvatskoj, Srbiji, Rumuniji i Bosni i Hercegovini. Za obavljanje postupaka morate doći u Beč.',
