    'pamb.ci.badge':'Obala Slonovače','pamb.ci.title':'Otkrijte Obalu Slonovače',
    'pamb.ci.p1':'Republika Obale Slonovače je zapadnoafrička zemlja, na jugu graniči sa Gvinejskim zalivom. Kao najveća privreda Zapadnoafričke ekonomske i monetarne unije (UEMOA), najveći je svetski proizvođač kakaa.',
    'pamb.ci.p2':'Abidžan, ekonomska prestonica, jedna je od najdinamičnijih metropola subsaharske Afrike. Jamusukro je politička i administrativna prestonica zemlje.',
    'pamb.ci.stat.area':'Površina','pamb.ci.stat.pop':'Stanovništvo','pamb.ci.stat.lang':'Zvanični jezik','pamb.ci.stat.lang.val':'Francuski','pamb.ci.stat.currency':'Valuta','pamb.ci.stat.indep':'Nezavisnost','pamb.ci.stat.indep.val':'7. avgust 1960.','pamb.ci.stat.capital':'Politička prestonica',
