    'pamb.org.badge':'Ambasada','pamb.org.title':'Organizaciona struktura',
    'pamb.org.p1':'Ambasada i Stalno predstavništvo organizovani su oko Stalnog predstavnika i specijalizovanog diplomatskog tima koji pokriva 9 zemalja centralne Evrope.',
    'pamb.org.p2':'Struktura obuhvata ministre savetnike, direktorku UNIDO-a, blagajnika, savetnike, prve sekretare i administrativno i tehničko osoblje.',
    'pamb.org.btn':'Pogledajte organizacionu strukturu →',
