    'cc.title':'Carte consulară', 'cc.eligibility.title':'Condiții de eligibilitate', 'cc.eligibility.text':'Să fiți cetățean ivorian care locuiește în circumscripția diplomatică a ambasadei (Austria, Ungaria, Croația, Serbia, Slovacia, Slovenia, România, Bosnia și Herțegovina, Moldova).',
    'cc.docs.title':'Dosar de furnizat', 'cc.docs.li1':'1 fotografie tip pașaport color cu fundal alb', 'cc.docs.li2':'Fotocopie a primelor 3 pagini ale pașaportului', 'cc.docs.li3':'Copie a actului de identitate (CNI, certificat de cetățenie)', 'cc.docs.li4':'Permis de ședere', 'cc.docs.li5':'Fotocopie a extrasului de naștere',
    'cc.docs.li6':'1 dovadă a adresei (atestat de cazare, fotocopie a unei facturi sau fotocopie a actului de identitate cu adresa înscrisă)', 'cc.docs.li7':'Chitanță de plată de 25 € pe site-ul: www.ci-embassyepay.org/embassy',
    'cc.f.nom':'Nume', 'cc.f.prenom':'Prenume', 'cc.f.naissance':'Data nașterii', 'cc.f.adresse':'Adresă', 'cc.f.email':'E-mail',
    'cc.docs.email.note':'După trimiterea acestui formular, vă rugăm să trimiteți o copie a tuturor documentelor de mai sus prin e-mail la <strong>sceconsul.autriche@diplomatie.gouv.ci</strong>, indicând numele și prenumele dumneavoastră ca subiect.',
    'cc.f.submit':'Trimiteți cererea →', 'cc.status.sending':'Trimitere în curs…', 'cc.status.success':'✓ Cerere trimisă cu succes!', 'cc.status.error':'Eroare la trimitere. Vă rugăm să încercați din nou sau să ne contactați direct.',
    'psrv.faq.q1':'Este absolut necesară o programare?', 'psrv.faq.a1':'Da, programarea este obligatorie pentru orice depunere de dosar. Niciun dosar nu va fi acceptat fără programare prealabilă. Puteți face o programare prin telefon sau e-mail.',
    'psrv.faq.q2':'Cât durează procesarea unui pașaport?', 'psrv.faq.a2':'Termenul mediu de procesare a unui pașaport biometric este de 4 până la 8 săptămâni. Acest termen depinde de condițiile de procesare de la Abidjan. În caz de urgență justificată corespunzător, un pașaport de urgență poate fi eliberat în 24 până la 72 de ore.',
    'psrv.faq.q3':'Taxele sunt rambursabile în caz de refuz?', 'psrv.faq.a3':'Nu, taxele consulare nu sunt rambursabile, inclusiv în caz de refuz al cererii. Prin urmare, este important să vă asigurați că dosarul dumneavoastră este complet înainte de a-l depune.',
    'psrv.faq.q4':'Îmi pot trimite dosarul prin poștă?', 'psrv.faq.a4':'Pentru anumite cereri simple (legalizarea copiilor, anumite certificate), trimiterea prin scrisoare recomandată este posibilă. Pentru cererile de pașaport și CNI, prezența fizică a solicitantului este obligatorie pentru preluarea amprentelor biometrice.',
    'psrv.faq.q5':'Locuiesc în Ungaria, îmi pot efectua demersurile la Viena?', 'psrv.faq.a5':"Da, Ambasada Côte d'Ivoire la Viena este competentă pentru toți cetățenii ivorieni cu reședința în Austria, Ungaria, Slovenia, Slovacia, Croația, Serbia, România și Bosnia și Herțegovina. Trebuie să vă deplasați la Viena pentru a vă efectua demersurile.",
    'pcon.h1':'Contact și program', 'pcon.desc':'Date de contact complete și program de funcționare al serviciului consular. Orice demers necesită o programare prealabilă.',
    'pcon.tel.lbl':'Telefon', 'pcon.email.lbl':'E-mail consular', 'pcon.addr.lbl':'Adresă', 'pcon.urg.lbl':'Urgențe consulare', 'pcon.urg.sub':'Disponibil 24/24 ore pentru urgențe',
