    'pcon.table.window':'Ghișeu consular',
    'pcon.urg2.title':'🚨 Urgențe consulare', 'pcon.urg2.desc':'În caz de urgență în afara programului (pierderea pașaportului, deces, spitalizare, arestare), serviciul nostru de permanență este disponibil 24/24 ore.',
