    'pcon.v1.tag':'Cu mașina sau taxiul', 'pcon.v1.rec':'Recomandat', 'pcon.v1.desc':'Venirea cu mașina sau taxiul este cel mai direct mod de a ajunge la ambasadă. Ajungeți direct în fața clădirii. Luați liftul până la etajul 3 și îndreptați-vă spre ușile 332-333.',
