    'pamb.ci.badge':"Côte d'Ivoire", 'pamb.ci.title':"Descoperă Côte d'Ivoire",
    'pamb.ci.p1':"Republica Côte d'Ivoire este o țară din Africa de Vest, mărginită la sud de Golful Guineei. Fiind prima economie a Uniunii Economice și Monetare Vest-Africane (UEMOA), este cel mai mare producător mondial de cacao.",
    'pamb.ci.p2':'Abidjan, capitala economică, este una dintre cele mai dinamice metropole din Africa Subsahariană. Yamoussoukro este capitala politică și administrativă a țării.',
    'pamb.ci.stat.area':'Suprafață', 'pamb.ci.stat.pop':'Populație', 'pamb.ci.stat.lang':'Limbă oficială', 'pamb.ci.stat.lang.val':'Franceză', 'pamb.ci.stat.currency':'Monedă', 'pamb.ci.stat.indep':'Independență', 'pamb.ci.stat.indep.val':'7 august 1960', 'pamb.ci.stat.capital':'Capitală politică',
    'pamb.ci.republic':"Republica Côte d'Ivoire",
    'pamb.org.badge':'Ambasada', 'pamb.org.title':'Organigramă',
    'pamb.org.p1':'Ambasada și Reprezentanța Permanentă sunt organizate în jurul unui Reprezentant Permanent și a unei echipe diplomatice specializate care acoperă 9 țări din Europa Centrală.',
    'pamb.org.p2':'Structura reunește Miniștri Consilieri, o Directoare ONUDI, un Casier, Consilieri, Prim-secretari și Personalul Administrativ și Tehnic.',
    'pamb.org.btn':'Consultați organigrama →',
    'pamb.net.badge':'Rețea externă', 'pamb.net.title':'Rețeaua diplomatică ivoriană în lume', 'pamb.net.desc':'Ambasade, consulate generale, misiuni și delegații permanente răspândite în întreaga lume.',
    'pamb.net.amb':'Ambasade', 'pamb.net.cg':'Consulate generale', 'pamb.net.mis':'Misiuni și delegații', 'pamb.net.circ':'Circumscripții', 'pamb.net.villes':'Orașe', 'pamb.net.pays':'Țări de reședință',
    'net.filter.all':'Toate posturile', 'net.filter.circ':'Circumscripții', 'net.filter.arcs':'Legături din Abidjan',
    'net.search.ph':'Căutați un oraș, o țară…', 'net.hint':'Selectați un punct pe hartă sau un post din lista de mai jos pentru a afișa detaliile.', 'net.close':'Vedere mondială',
    'net.footer':'Ambasadă = reprezentare bilaterală pe lângă un stat · Consulat general = post consular pentru o circumscripție · Misiune permanentă = reprezentare pe lângă o organizație internațională.',
    'badge.ci':"Côte d'Ivoire", 'ci.title':"Descoperă Côte d'Ivoire", 'ci.republic':"Republica Côte d'Ivoire",
    'ci.area':'Suprafață', 'ci.pop':'Populație', 'ci.indep':'Independență', 'ci.indep.val':'7 august 1960', 'ci.capital':'Capitală',
    'pamb.mis.p1':"Ambasada Republicii Côte d'Ivoire în Austria este reprezentanța diplomatică oficială a Côte d'Ivoire la Viena. Asigură apărarea intereselor ivoriene, dezvoltarea relațiilor bilaterale și protecția cetățenilor săi.",
    'pamb.mis.p2':'Înființată în conformitate cu Convenția de la Viena privind relațiile diplomatice din 1961, Ambasada îndeplinește o dublă misiune: diplomatică (reprezentarea statului pe lângă țara gazdă) și consulară (asistență pentru cetățenii ivorieni cu reședința în jurisdicția sa).',
    'pamb.mis.p3':'În cadrul competenței sale teritoriale, Ambasada acoperă 9 țări: Austria, Ungaria, Slovenia, Slovacia, Croația, Serbia, România și Bosnia și Herțegovina.',
    'pamb.stat.countries':'țări în Circumscripția Diplomatică', 'pamb.stat.conv':'Convenția de la Viena', 'pamb.stat.ci':"Côte d'Ivoire", 'pamb.stat.host':'Țară gazdă',
    'pamb.amb.title':"Ambasador Extraordinar și Plenipotențiar al Republicii Côte d'Ivoire în Austria",
    'pamb.amb.p1':"Excelența Sa domnul Cissé Yacouba este acreditat pe lângă Republica Austria în calitate de Ambasador Extraordinar și Plenipotențiar al Republicii Côte d'Ivoire. Este de asemenea acreditat pe lângă Ungaria, Slovenia, Slovacia, Croația, Serbia, România și Bosnia și Herțegovina.",
    'pamb.amb.p2':"Cu o lungă carieră diplomatică în serviciul Côte d'Ivoire, Excelența Sa domnul Cissé Yacouba reprezintă interesele republicii ivoriene, promovează relațiile bilaterale și multilaterale și coordonează ansamblul serviciilor Ambasadei.",
    'porg.breadcrumb':'Organigramă', 'porg.h1':'Organigramă', 'porg.desc':"Structura organizatorică a Ambasadei și Reprezentanței Permanente a Côte d'Ivoire la Viena.",
