    'pdec.mob.table.ticket':'Bilet', 'pdec.mob.table.price':'Tarif (2026)', 'pdec.mob.table.single':'Călătorie simplă (Einzelfahrt)', 'pdec.mob.table.single.val':'3,20 € hârtie / 3,00 € aplicație',
    'pdec.mob.table.day':'Abonament 24h', 'pdec.mob.table.day.val':'10,20 €', 'pdec.mob.table.week':'Bilet digital 7 zile', 'pdec.mob.table.week.val':'25,20 €', 'pdec.mob.table.citycard':'Vienna City Card (24h)', 'pdec.mob.table.citycard.val':'de la ~19 €',
    'pdec.mob.rule.badge':'Regula de aur', 'pdec.mob.rule.text':'Validați biletul de hârtie în cutiile albastre înainte de a urca — biletele digitale (aplicație/online) sunt validate automat. Amendă în caz de control fără bilet valabil: 135 €.',
    'pdec.mob.airport.note':'⚠️ Aeroportul este în afara zonei centrale (Zona 100): un bilet oraș nu este suficient, este nevoie de un supliment de zonă exterioară (~2,20 €) sau de un bilet specific de aeroport.',
    'pdec.mob.app.badge':'Aplicație recomandată', 'pdec.mob.app.title':'Descărcați aplicația WienMobil', 'pdec.mob.app.desc':'Aplicația oficială Wiener Linien vă permite să vă cumpărați biletele (mai ieftine decât pe hârtie), să vă planificați traseele în timp real și să rezervați biciclete cu autoservire.',
