    'pdec.disclaimer':'Instituțiile și serviciile menționate sunt furnizate cu titlu informativ. Ambasada nu recomandă și nu garantează niciun furnizor privat. Tarife orientative, susceptibile de modificare.',
    'pdec.food.badge':'Mese', 'pdec.food.title':'Unde să mâncați la Viena', 'pdec.food.delivery.title':'Comandă online', 'pdec.food.delivery.desc':'Mai multe platforme de livrare a mesei sunt disponibile la Viena:',
    'pdec.food.african.title':'Bucătărie africană și vest-africană', 'pdec.food.african.desc':'Pentru a regăsi aromele de acasă — orez jollof, mafé, pui la grătar, attiéké:',
    'pdec.food.viennese.title':'Specialități vieneze de gustat', 'pdec.food.viennese.desc':'Șnițel vienez, tort Sacher, strudel cu mere — și faceți un tur la piața Naschmarkt pentru a descoperi aromele locale.',
    'pdec.sights.badge':'Vizitare', 'pdec.sights.title':'Locuri esențiale din Viena', 'pdec.sights.desc':'Câteva situri emblematice de descoperit în timpul șederii dumneavoastră.',
    'pdec.sights.schoenbrunn.title':'Castelul Schönbrunn', 'pdec.sights.schoenbrunn.desc':'Fosta reședință de vară imperială și grădinile sale clasate UNESCO.',
