    'pdec.practical.german.title':'Câteva cuvinte germane utile', 'pdec.practical.german.li1':'Grüß Gott — Bună ziua', 'pdec.practical.german.li2':'Danke — Mulțumesc', 'pdec.practical.german.li3':'Bitte — Vă rog / Cu plăcere', 'pdec.practical.german.li4':'Entschuldigung — Scuze / Mă scuzați', 'pdec.practical.german.li5':'Wie viel? — Cât costă?',
    'pdec.practical.etiquette.title':'Etichetă și viață practică', 'pdec.practical.etiquette.desc':'Punctualitatea este foarte apreciată. Magazinele sunt de obicei închise duminica. Sortarea deșeurilor este riguroasă, iar transportul public se trăiește în liniște.',
    'pdec.practical.excursions.title':'Excursii de la Viena', 'pdec.practical.excursions.desc':'Bratislava (~1 h), valea Wachau, Salzburg sau Graz sunt ușor accesibile cu trenul prin ÖBB.',
    'pdec.practical.diaspora.title':'Comunitatea ivoriană și diaspora', 'pdec.practical.diaspora.desc':'Contactați Ambasada sau urmăriți rețelele noastre sociale pentru a fi informat despre evenimentele comunității ivoriene din Austria.',
