    'dl.f03.eyebrow':'Maloljetnik','dl.f03.title':'Roditeljska izjava','dl.f03.sub':'Saglasnost za pasoš i/ili izvod iz matične knjige rođenih maloljetnika','dl.f03.desc':'Saglasnost koju izdaje jedan ili oba roditelja za izdavanje pasoša ili izvoda iz matične knjige rođenih za maloljetno dijete. Potreban je ovjeren potpis.','dl.f03.size':'PDF · 100 KB',
    'dl.f04.eyebrow':'Viza','dl.f04.title':'Obrazac zahtjeva za vizu','dl.f04.sub':'Obična, kurtoazna ili diplomatska viza','dl.f04.desc':'Obrazac za svaki zahtjev za ulaznu vizu za Obalu Slonovače. Potrebno je popuniti sva obavezna polja. Potrebna je nedavna fotografija.','dl.f04.size':'PDF · 125 KB',
    'dl.f05.eyebrow':'Matične knjige','dl.f05.title':'Prepis izvoda iz matične knjige rođenih','dl.f05.sub':'Djeca rođena u inostranstvu od roditelja sa Obale Slonovače','dl.f05.desc':'Obrazac za upis stranog izvoda iz matične knjige rođenih u matične knjige Obale Slonovače. Obavezno za sticanje državljanstva i pasoša.','dl.f05.size':'PDF · 131 KB',
    'dl.f06.eyebrow':'Punomoć','dl.f06.title':'Konzularna punomoć','dl.f06.sub':'Ovlaštenje za postupanje u ime trećeg lica','dl.f06.desc':'Omogućava ovlaštenom licu da obavlja administrativne poslove u vaše ime kod ambasade ili na teritoriji Obale Slonovače.','dl.f06.size':'PDF · 89 KB',
    'dl.f07.eyebrow':'Ovjera','dl.f07.title':'Zahtjev za ovjeru','dl.f07.sub':'Ovjera administrativnih ili javnobilježničkih dokumenata','dl.f07.desc':'Obrazac za ovjeru dokumenata Obale Slonovače ili stranih dokumenata namijenjenih upotrebi na Obali Slonovače ili u trećoj zemlji. Primjenjuje se na javnobilježničke, administrativne i komercijalne isprave.','dl.f07.size':'PDF · 121 KB',
    'dl.f08.eyebrow':'Putni list','dl.f08.title':'Zahtjev za putni list','dl.f08.sub':'Privremena putna isprava u hitnim slučajevima','dl.f08.desc':'Privremena putna isprava izdata u slučaju gubitka, krađe ili isteka pasoša. Važi za putovanje u jednom pravcu za Obalu Slonovače.','dl.f08.size':'PDF · 139 KB',
    'dl.f09.eyebrow':'Državljanstvo','dl.f09.title':'Odricanje od državljanstva Obale Slonovače','dl.f09.sub':'Zahtjev za potvrdu o proslijeđivanju odricanja','dl.f09.desc':'Obrazac koji je potrebno popuniti za pokretanje postupka odricanja od državljanstva Obale Slonovače. Podnosi se ambasadi zajedno sa potrebnim dokumentima.','dl.f09.size':'PDF · 89 KB',
