    'cta.title':'Potrebna vam je konzularna pomoć?','cta.desc':'Naš tim vam stoji na raspolaganju za sve administrativne postupke. Zakažite termin online ili nas kontaktirajte direktno.','cta.btn1':'Zakažite termin','cta.btn2':'Pregled usluga',
    'ann.h1':'Informacije i obavještenja','ann.desc':'Ovdje pronađite sve zvanične informacije, važna obavještenja i saopćenja Ambasade Obale Slonovače u Beču.',
    'ann.pinned.label':'Zakačeno — Hitno','ann.pinned.title':'Vanredno zatvaranje — Državni praznik Obale Slonovače','ann.pinned.desc':'Ambasada Obale Slonovače u Beču bit će <strong>zatvorena u petak, 7. augusta 2026.</strong>, povodom Državnog praznika Republike Obale Slonovače (66. godišnjica nezavisnosti). Usluge će se redovno nastaviti u ponedjeljak, 10. augusta 2026, u 09.30.','ann.pinned.date':'Objavljeno 25. maja 2026.',
    'ann.filter.all':'Sve','ann.filter.urgent':'Hitno','ann.filter.admin':'Administrativno','ann.filter.event':'Događaji','ann.filter.communique':'Saopćenja',
    'ann.cat.mission':'Ekonomska misija','ann.cat.diplo':'Diplomatija','ann.cat.actu':'Vijesti','ann.cat.communique':'Saopćenje',
    'ann.btn.read':' Pročitaj članak','ann.btn.readfull':' Pročitaj cijelo saopćenje','ann.empty':'Trenutno nema obavještenja u ovoj kategoriji.',
    'ann.sidebar.links':'Korisni linkovi','ann.sidebar.passport':'Obnova pasoša','ann.sidebar.visa':'Zahtjev za vizu','ann.sidebar.civil':'Matične knjige','ann.sidebar.rdv':'Zakažite termin','ann.sidebar.hours':'Radno vrijeme','ann.sidebar.contact':'Direktan kontakt',
    'ann.sub.title':'Primajte obavještenja','ann.sub.desc':'Prijavite se da biste bili obaviješteni o novim obavještenjima i važnim informacijama.','ann.sub.btn':'Prijava na obavještenja',
    'ann.a1.title':'Ekonomska misija: Aka Aouélé predvodi delegaciju Ekonomskog, socijalnog, ekološkog i kulturnog vijeća (CESEC) u Austriju','ann.a1.desc':'Predsjednik CESEC-a, Aka Aouélé, predvodio je delegaciju Obale Slonovače u Austriju u okviru ekonomske misije usmjerene na jačanje razmjena i saradnje između Obale Slonovače i njenih evropskih partnera.',
    'ann.a2.title':'Diplomatija Obale Slonovače u fokusu u Beču: Obala Slonovače preuzima predsjedavanje Organizacijom Ugovora o sveobuhvatnoj zabrani nuklearnih proba','ann.a2.desc':'Obala Slonovače preuzela je predsjedavanje Pripremnom komisijom Organizacije Ugovora o sveobuhvatnoj zabrani nuklearnih proba (CTBTO), što predstavlja važnu prekretnicu diplomatije Obale Slonovače na međunarodnoj sceni u Beču.',
    'ann.a3.title':'Civilna nuklearna energija: Obala Slonovače zagovara jaču podršku Međunarodne agencije za atomsku energiju','ann.a3.desc':'Obala Slonovače je u Beču, tokom rada IAEA, izrazila želju za pojačanom podrškom u razvoju svog civilnog nuklearnog programa.',
    'ann.a4.title':'Diplomatija Obale Slonovače u Austriji: ambasador Cissé Yacouba razgovarao sa guvernerom Vorarlberga','ann.a4.desc':'Njegova Ekselencija gospodin Cissé Yacouba, ambasador Obale Slonovače u Austriji, sastao se sa guvernerom savezne pokrajine Vorarlberg u okviru jačanja bilateralnih odnosa između Obale Slonovače i Austrije.',
    'ann.a5.title':'Zvanično saopćenje — Predaja akreditiva','ann.a5.desc':'Njegova Ekselencija gospodin Cissé Yacouba, izvanredni i opunomoćeni ambasador Republike Obale Slonovače, predao je svoja akreditivna pisma saveznom predsjedniku Republike Austrije na zvaničnoj svečanosti u palati Hofburg u Beču.',
    'ann.a6.title':'Obala Slonovače i CTBTO sklopile su u Abidžanu partnerstvo u oblasti nuklearne sigurnosti','ann.a6.desc':'26. juna 2026. u Abidžanu su Obala Slonovače i Organizacija Ugovora o sveobuhvatnoj zabrani nuklearnih proba (CTBTO) potpisale sporazum o partnerstvu usmjeren na jačanje Međunarodnog sistema nadzora (IMS). Ambasador Cissé Yacouba predstavljao je delegaciju Obale Slonovače zajedno sa ministricom vanjskih poslova Nialé Kaba i izvršnim sekretarom Robertom Floydom.','ann.a6.date':'26. juni 2026.',
