    'cc.docs.email.note':'Nakon slanja ovog obrasca, molimo pošaljite kopiju svih gore navedenih dokumenata emailom na <strong>sceconsul.autriche@diplomatie.gouv.ci</strong>, navodeći svoje ime i prezime u naslovu.',
    'cc.f.submit':'Pošalji zahtjev →','cc.status.sending':'Slanje u toku…','cc.status.success':'✓ Zahtjev je uspješno poslan!','cc.status.error':'Greška prilikom slanja. Pokušajte ponovo ili nas kontaktirajte direktno.',
    'psrv.faq.q1':'Da li je termin zaista neophodan?','psrv.faq.a1':'Da, zakazivanje termina obavezno je za svako podnošenje dokumentacije. Bez prethodnog termina, nijedna dokumentacija neće biti prihvaćena. Termin možete zakazati telefonom ili emailom.',
    'psrv.faq.q2':'Koliko traje obrada pasoša?','psrv.faq.a2':'Prosječan rok obrade biometrijskog pasoša je 4 do 8 sedmica. Ovaj rok zavisi od uslova obrade u Abidžanu. U slučaju propisno opravdane hitnosti, hitni pasoš može biti izdat u roku od 24 do 72 sata.',
    'psrv.faq.q3':'Da li se takse vraćaju u slučaju odbijanja?','psrv.faq.a3':'Ne, konzularne takse se ne vraćaju, čak ni u slučaju odbijanja zahtjeva. Zato je važno da prije podnošenja provjerite da li je vaša dokumentacija kompletna.',
    'psrv.faq.q4':'Mogu li poslati svoju dokumentaciju poštom?','psrv.faq.a4':'Za pojedine jednostavne zahtjeve (ovjera kopija, određena uvjerenja) moguće je slanje preporučenom poštom. Za zahtjeve za pasoš i ličnu kartu obavezno je lično prisustvo podnosioca zahtjeva radi uzimanja biometrijskih otisaka.',
    'psrv.faq.q5':'Živim u Mađarskoj, mogu li svoje postupke obaviti u Beču?','psrv.faq.a5':'Da, Ambasada Obale Slonovače u Beču nadležna je za sve državljane Obale Slonovače sa prebivalištem u Austriji, Mađarskoj, Sloveniji, Slovačkoj, Hrvatskoj, Srbiji, Rumuniji i Bosni i Hercegovini. Za obavljanje postupaka morate doći u Beč.',
    'pcon.h1':'Kontakt i radno vrijeme','pcon.desc':'Kompletni kontakt podaci i radno vrijeme konzularne službe. Svaki postupak zahtijeva prethodno zakazan termin.',
