    'pamb.h1':'Ambasada Obale Slonovače','pamb.desc':'Zvanično predstavništvo Republike Obale Slonovače u Austriji sa sjedištem u Beču, koje obezbjeđuje diplomatske odnose i konzularne usluge za 9 zemalja centralne Evrope.',
    'pamb.mis.badge':'Naša misija','pamb.mis.title':'Diplomatska i konzularna misija',
    'pamb.pays.badge':'Nadležnost','pamb.pays.title':'Diplomatski okrug','pamb.pays.sub':'Ambasada Obale Slonovače u Beču pokriva diplomatski okrug sljedećih 9 zemalja.',
