    'net.footer':'Ambasada = bilateralno predstavništvo pri državi · Generalni konzulat = konzularno mjesto za okrug · Stalna misija = predstavništvo pri međunarodnoj organizaciji.',
    'badge.ci':'Obala Slonovače','ci.title':'Otkrijte Obalu Slonovače','ci.republic':'Republika Obala Slonovače',
    'ci.area':'Površina','ci.pop':'Stanovništvo','ci.indep':'Nezavisnost','ci.indep.val':'7. avgust 1960.','ci.capital':'Prijestonica',
    'pamb.mis.p1':'Ambasada Republike Obale Slonovače u Austriji zvanično je diplomatsko predstavništvo Obale Slonovače u Beču. Obezbjeđuje odbranu interesa Obale Slonovače, razvoj bilateralnih odnosa i zaštitu svojih državljana.',
    'pamb.mis.p2':'Osnovana u skladu sa Bečkom konvencijom o diplomatskim odnosima iz 1961. godine, Ambasada ispunjava dvostruku misiju: diplomatsku (predstavljanje države pri državi domaćinu) i konzularnu (pomoć državljanima Obale Slonovače sa prebivalištem u njenoj nadležnosti).',
    'pamb.mis.p3':'U okviru svoje teritorijalne nadležnosti Ambasada pokriva 9 zemalja: Austriju, Mađarsku, Sloveniju, Slovačku, Hrvatsku, Srbiju, Rumuniju i Bosnu i Hercegovinu.',
    'pamb.stat.countries':'zemalja u diplomatskom okrugu','pamb.stat.conv':'Bečka konvencija','pamb.stat.ci':'Obala Slonovače','pamb.stat.host':'Zemlja domaćin',
    'pamb.amb.title':'Izvanredni i opunomoćeni ambasador Republike Obale Slonovače u Austriji',
    'pamb.amb.p1':'Njegova Ekselencija gospodin Cissé Yacouba akreditovan je pri Republici Austriji kao izvanredni i opunomoćeni ambasador Republike Obale Slonovače. Takođe je akreditovan pri Mađarskoj, Sloveniji, Slovačkoj, Hrvatskoj, Srbiji, Rumuniji i Bosni i Hercegovini.',
    'pamb.amb.p2':'Sa dugom diplomatskom karijerom u službi Obale Slonovače, Njegova Ekselencija gospodin Cissé Yacouba zastupa interese republike Obale Slonovače, promoviše bilateralne i multilateralne odnose i koordinira sve službe Ambasade.',
    'porg.breadcrumb':'Organizaciona struktura','porg.h1':'Organizaciona struktura','porg.desc':'Organizaciona struktura Ambasade i Stalnog predstavništva Obale Slonovače u Beču.',
